import{$ as e,B as t,et as n,pt as r}from"./chunks/framework.KBYRAceO.js";var i=JSON.parse(`{"title":"에이전틱 디자인 리뷰","description":"기획자와 디자이너가 없는 조직에서 일하는 개발자의 디자인 리뷰 관점을 다룹니다.","frontmatter":{"title":"에이전틱 디자인 리뷰","date":"2026-07-03T07:00+09:00","description":"기획자와 디자이너가 없는 조직에서 일하는 개발자의 디자인 리뷰 관점을 다룹니다.","tags":["개발자","디자인","에이전틱 리뷰"]},"headers":[],"relativePath":"posts/agentic-design-review.md","filePath":"posts/agentic-design-review.md","lastUpdated":1784727263000}`),a={name:`posts/agentic-design-review.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="에이전틱-디자인-리뷰" tabindex="-1">에이전틱 디자인 리뷰 <a class="header-anchor" href="#에이전틱-디자인-리뷰" aria-label="Permalink to “에이전틱 디자인 리뷰”">​</a></h1><p><mark>&quot;디자인 개선해줘&quot;</mark>, <mark>&quot;사용성 있게 바꿔줘.&quot;</mark></p><p>저처럼 <strong>기획자와 디자이너가 없는 조직에서 일하는</strong> 개발자들이 요즘 들어 AI 에이전트에게 가장 흔하게 요청하는 형태겠죠? 스스로 디자인 감각이 부족하다고 생각하기에 AI의 힘을 빌려 제품의 사용성을 그럴듯하게 탈바꿈하길 기대하지만, 안타깝게도 에이전트와 눈높이를 맞춰 기대에 부응하는 결과물을 빠르게 얻기는 어려움을 느껴요. 결국 사용자 친화적인 화면이 아니면서, 나조차 마음에 들지 않는 화면으로 남게 되는 것 같아요.</p><p>그렇다면 나와 같이 디자인 감각이 부족한 개발자는 대체 어떻게 해야 할까요? 에이전트를 파트너 삼아 제품 디자인과 사용성을 올바르게 리뷰하고 개선하기 위해서는 어떤 생각을 가져야할까요?</p><h2 id="에이전틱한-디자인" tabindex="-1">에이전틱한 디자인 <a class="header-anchor" href="#에이전틱한-디자인" aria-label="Permalink to “에이전틱한 디자인”">​</a></h2><p>AI 에이전트가 그리는 화면들을 유심히 보다 보면 매번 비슷한 느낌의 천편일률적인 스타일이 반복되는 것을 보게 돼요. 이러한 정형화된 형태를 흔히 <mark>&#39;AI 슬롭(AI Slop)&#39;</mark>이라고 부르는데, 최근 공유되는 <a href="https://impeccable.style/slop/" target="_blank" rel="noreferrer">Impeccable</a> 같은 에이전트 디자인 스킬도 이러한 AI Slop 패턴을 개선하려는 노력 중 하나랍니다. 하지만 아무리 전용 디자인 스킬이나 <code>DESIGN.md</code> 가이드를 추가하더라도, 이것이 <strong>애초에 디자인 시스템을 온전히 대체할 수는 없다</strong>는 본질적인 한계가 있어요.</p><p>결국 도구와 기술이 발전하더라도 <mark>전문적인 디자인적 개입과 시각</mark>이 필수적일 수밖에 없는 셈이죠. 하지만 디자인 인력은 물론이고 제대로 된 디자인 시스템조차 부재한 조직에서는 이 간극이 더욱 두드러져요. 에이전트가 만들어낸 결과물을 보며 어딘가 모르게 어색하다고 느끼면서도, 무엇을 어떻게 수정해야 하는지 명확한 피드백을 주지 못하는 상황이 발생하기 때문이에요.</p><p>이처럼 디자인 지식이 부족한 상태에서 막연하게 &quot;화면 디자인을 개선해줘&quot;라고 요청하는 모습은, 명확한 요구 명세서 없이 그저 &quot;알아서 잘 만들어달라&quot;라고 요구하는 B2B 고객사의 모습과 크게 다르지 않답니다.</p><h2 id="개발자의-디자인-리뷰" tabindex="-1">개발자의 디자인 리뷰 <a class="header-anchor" href="#개발자의-디자인-리뷰" aria-label="Permalink to “개발자의 디자인 리뷰”">​</a></h2><p>그렇다면 디자인 감각이 부족한 개발자가 에이전트와 협업하며 제품의 디자인과 사용성을 올바르게 리뷰하려면 어떻게 해야 할까요? 결국 우리가 원하는 바를 명확히 요구하기 위해, 스스로 <strong>기본적인 디자인 레이아웃과 용어</strong>를 공부하는 수밖에 없어요.</p><p><a href="https://github.com/google-labs-code/design.md" target="_blank" rel="noreferrer">DESIGN.md</a> 템플릿을 모아둔 <a href="https://getdesign.md/" target="_blank" rel="noreferrer">사이트</a>가 있더라도, 기본 지식이 없다면 그 의미를 온전히 이해하기 어려워요. 그렇기에 <a href="https://www.youtube.com/watch?v=7vbof7PQUAI" target="_blank" rel="noreferrer">9년차가 알려주는 UI 실무 용어와 용어별 업무 적용 꿀팁까지!</a> 같은 자료를 참고하면서 에이전트와 소통할 수 있는 최소한의 <mark>&#39;디자인 어휘&#39;</mark>를 갖추는 노력이 필요하답니다.</p><p>만약 당장 명확한 방향성을 제시하기 막막하다면, 우선 <strong>5개 이내의 구체적인 디자인 개선 시안</strong>을 보여달라고 요청해 보세요. 제안받은 시안들을 기존 화면에 직접 대입해 비교하면서 추가 시안을 보완해 나가는 것이죠. 이 과정에서 가장 나아 보이는 시안을 골라 에이전트에게 <mark>구조와 디자인 원리를 설명해 달라</mark>고 요청하면 자연스럽게 디자인을 배울 수 있어요.</p><p>그 후 완성된 화면을 바탕으로 디자인 시스템의 뼈대가 되는 <a href="https://www.krds.go.kr/html/site/style/style_07.html" target="_blank" rel="noreferrer">디자인 토큰(Design Tokens)</a> 추출을 에이전트에게 요청하면 된답니다. 에이전트가 제시하는 시안 피드백을 비판적으로 수용하고 조율해 나가면서, 스스로 <mark>디자인을 바라보는 안목</mark>을 길러가야 해요. 과거 개발자가 좋은 아키텍처와 <strong>클린 코드</strong>를 작성하기 위해 끝없이 공부하고 실천했던 것처럼 말이에요.</p><p>Addy Osmani가 <a href="https://addyo.substack.com/p/agentic-code-review" target="_blank" rel="noreferrer">Agentic Code Review</a>에서 에이전트를 통한 코드 리뷰의 패러다임 변화를 짚었듯, 디자인 영역에서도 에이전트의 결과물을 검수하고 다듬는 <mark>&#39;에이전틱 디자인 리뷰(Agentic Design Review)&#39;</mark> 능력이 갈수록 중요해지고 있어요. 결국 에이전트가 내놓은 결과물이 올바른 사용자 경험에 부합하는지 벼리처럼 감별하고 다듬는 <strong>정교한 디자인 검수 능력</strong>이 앞으로 개발자에게 가장 중요한 역량이 될 것이랍니다.</p>`,14)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};